import{_ as o,l as r,o as e,c as n,v as t,p,x as l,d as s,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"公钥与信封","description":"","frontmatter":{"title":"公钥与信封","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pubkey-envelope.md","filePath":"cs/pubkey-envelope.md","lastUpdated":1789023840000}'),A={name:"cs/pubkey-envelope.md"};function c(h,a,_,m,f,u){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="公钥与信封" tabindex="-1">公钥与信封 <a class="header-anchor" href="#公钥与信封" aria-label="Permalink to &quot;公钥与信封&quot;">​</a></h1><div class="epigraph"><p>公开的钥匙只能封上；打开或签名要用留下的那一半。会话仍用对称，公钥只运密钥。</p><footer>—— Diffie and Hellman, New Directions in Cryptography, IEEE TIT 1976</footer></div><p><a href="/cs/block-modes">上一课</a>给出 AEAD，前提是共享密钥已在。本课不重写 GCM。缺口是：第一次见面如何得到那把密钥，而不先有安全信道。公钥加密：公钥可公开，私钥保密。实践几乎总是<strong>信封</strong>：用公钥封装随机会话密钥，大数据仍走对称。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称密钥若靠事先邮寄，规模炸裂；若靠明文套接字传送，与不加密相同。Diffie–Hellman 1976 的方向是：公开算法与公钥，使没有预共享秘密的双方能得到共同密钥。RSA 一类公钥加密可直接封密钥。缺口不是数论课，而是混合加密这一层工程对象。</p><p><span class="marginnote">Goldwasser and Micali 要求公钥方案也有语义安全（随机化加密）。确定性公钥加密泄漏相等性，与 ECB 同类错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>信封：发送方抽会话密钥 \\(k\\)，用接收方公钥封装 \\(k\\)，用 \\(k\\) 做 AEAD。DH/ECDHE：双方临时指数，得到共享秘密再派生 \\(k\\)，提供前向保密——长期私钥泄露不回溯旧会话。本课不写椭圆曲线方程，只锁定：长期密钥用于认证与封装，会话密钥短命。</p>',8)),(e(),p(E,null,{default:l(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%85%AC%E9%92%A5%22%5D%20--%3E%20ENV%5B%22%E5%B0%81%E8%A3%85%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%22%5D%0A%20%20SYM%5B%22%E5%AF%B9%E7%A7%B0%20AEAD%22%5D%20--%3E%20DATA%5B%22%E5%A4%A7%E6%89%B9%E6%98%8E%E6%96%87%22%5D%0A%20%20ENV%20--%3E%20SYM%0A%20%20ENV%20--%3E%20HASH%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%93%88%E5%B8%8C%E4%B8%8E%E7%A2%B0%E6%92%9E%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公钥运算贵，只保护几十字节的密钥；吞吐量仍在对称层。认证尚未解决：你封的是<strong>谁的</strong>公钥？中间人可以换成自己的公钥。那是证书课。本课只让「没有预共享对称键也能建会话」成立，身份绑定另做。</p><p>信封把公钥运算的次数压到每个会话几次，与消息长度解耦。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「公钥」写成「更安全的对称」。它解决分发与某些认证，不自动更强。也不把量子威胁写成已插入主干的算法更换课；后量子是附录级对照，本课仍用 DH/RSA 的机制角色。私钥一旦进内存，威胁模型回到「能读进程」。</p><p>封装失败（错误的 \\(pk\\)）会把会话键交给错误主体，这是认证缺口，不是对称层的锅。后课默认：会话用对称；公钥运密钥或做签名。抗碰撞哈希是签名与承诺的前置零件。</p><p>长期私钥的保护（HSM、权限、轮换）属于威胁模型里的端点，不是 DH 算术能代替的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>前向保密依赖临时 DH，长期私钥泄露不回溯旧 \\(k\\)。</p></li><li><p>后课哈希为签名与承诺提供固定长摘要。</p></li><li><p>对称要共享密钥；本课用公钥信封与 DH 派生会话键。</p></li><li><p>大批数据仍 AEAD；公钥不替代对称。</p></li><li><p>身份与公钥的绑定尚未做；哈希先作为零件。</p></li><li><p>出处：Diffie and Hellman, 1976；对照 RSA；Goldwasser and Micali。</p></li></ul>',9))])}const B=o(A,[["render",c]]);export{k as __pageData,B as default};
